#[allow(dead_code)]
pub struct ANTLRv4ValidatedTreeWalker;

#[allow(dead_code)]
impl ANTLRv4ValidatedTreeWalker {
    pub fn walk<E, T: ANTLRv4ValidatedListener<E>>(
        listener: &mut T,
        tree: ValidatedRuleNode<'_>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree.node(), None)
    }

    pub fn walk_with_invocation_states<E, T: ANTLRv4ValidatedListener<E>>(
        listener: &mut T,
        tree: ValidatedRuleNode<'_>,
        parent_invocation_states: Vec<isize>,
    ) -> Result<(), E> {
        Self::__walk(listener, tree.node(), Some(parent_invocation_states))
    }

    fn __walk<E, T: ANTLRv4ValidatedListener<E>>(
        listener: &mut T,
        tree: antlr4_runtime::Node<'_>,
        invocation_states: Option<Vec<isize>>,
    ) -> Result<(), E> {
        let mut callbacks = __ANTLRv4ValidatedTreeWalkerCallbacks(listener);
        antlr4_runtime::generated::walk_generated(tree, invocation_states, &mut callbacks)
    }
}

pub type ValidatedParseTreeWalker = ANTLRv4ValidatedTreeWalker;



